document.addEventListener('DOMContentLoaded',(()=>{const SECURITY_CONFIG={maxRequests:10,windowMinutes:60,blockDurationMinutes:30};let requestLog=[],isBlocked=false,blockUntil=0;function checkRateLimit(){const now=Date.now(),windowMs=SECURITY_CONFIG.windowMinutes*60*1000;if(isBlocked&&now<blockUntil)return{allowed:false,blocked:true,remaining:Math.ceil((blockUntil-now)/1000/60)};if(isBlocked&&now>=blockUntil){isBlocked=false;requestLog=[]}requestLog=requestLog.filter(t=>now-t<windowMs);if(requestLog.length>=SECURITY_CONFIG.maxRequests){isBlocked=true;blockUntil=now+SECURITY_CONFIG.blockDurationMinutes*60*1000;return{allowed:false,blocked:true,remaining:SECURITY_CONFIG.blockDurationMinutes}}requestLog.push(now);return{allowed:true,blocked:false}}function showSecurityBlock(m){alert("⚠️ Segurança: Muitas requisições detectadas.\nTente novamente em "+m+" minuto(s).")}const DOM={setupScreen:document.getElementById('setup-screen'),sendingScreen:document.getElementById('sending-screen'),startBtn:document.getElementById('startBtn'),backBtn:document.getElementById('backBtn'),nextBtn:document.getElementById('nextBtn'),numbersInput:document.getElementById('numbers'),messageInput:document.getElementById('message'),countLabel:document.getElementById('countLabel'),currentIndexEl:document.getElementById('currentIndex'),totalNumbersEl:document.getElementById('totalNumbers'),currentNumberEl:document.getElementById('currentNumber'),progressBar:document.getElementById('progressBar'),progressPercent:document.getElementById('progressPercent'),sendLink:document.getElementById('sendLink'),themeToggles:document.querySelectorAll('.theme-toggle'),themeIcons:document.querySelectorAll('[id^="themeIcon"]'),toastContainer:document.getElementById('toast-container')};function debounce(f,w){let t;return function(...a){clearTimeout(t);t=setTimeout(()=>f(...a),w)}}let numberList=[],currentIndex=0,rafId=null;function setTheme(d){if(d){document.body.classList.add('dark-theme');updateThemeIcons('sun')}else{document.body.classList.remove('dark-theme');updateThemeIcons('moon')}localStorage.setItem('theme',d?'dark':'light')}function updateThemeIcons(t){const s='<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"></circle><line x1="12" y1="1" x2="12" y2="3"></line><line x1="12" y1="21" x2="12" y2="23"></line><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"></line><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"></line><line x1="1" y1="12" x2="3" y2="12"></line><line x1="21" y1="12" x2="23" y2="12"></line><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"></line><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"></line></svg>',m='<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg>';DOM.themeIcons.forEach(i=>{i.innerHTML=t==='sun'?s:m})}const savedTheme=localStorage.getItem('theme')||'light';setTheme(savedTheme==='dark');DOM.themeToggles.forEach(t=>{t.addEventListener('click',()=>{const d=document.body.classList.toggle('dark-theme');setTheme(d)})});function showToast(msg){const e=document.createElement('div');e.className='toast';e.textContent=msg;DOM.toastContainer.appendChild(e);e.offsetHeight;e.style.opacity='1';e.style.transform='translateY(0)';setTimeout(()=>{e.style.opacity='0';e.style.transform='translateY(-20px)';setTimeout(()=>e.remove(),300)},3000)}const updateCountLabel=debounce(()=>{const raw=DOM.numbersInput.value.split('\n').filter(l=>l.trim()!=='');const valid=raw.filter(l=>isValidPhone(l.trim()));const inv=raw.length-valid.length;DOM.countLabel.textContent=`${valid.length} / 20 números válidos`;DOM.countLabel.style.color=valid.length>20?'var(--error-color)':'var(--text-muted)';if(inv>0){DOM.countLabel.textContent+=` (${inv} inválido(s))`;DOM.countLabel.style.color='var(--error-color)'}},150);DOM.numbersInput.addEventListener('input',e=>{let v=e.target.value;v=v.replace(/[^0-9\n+]/g,'');e.target.value=v;updateCountLabel()});function isValidPhone(p){const c=p.replace(/[\s+\-()\.]/g,'');if(!/^\d+$/.test(c))return false;if(c.length<10||c.length>15)return false;if(c.startsWith('0'))return false;if(/^(\d)\1+$/.test(c))return false;return true}DOM.startBtn.addEventListener('click',()=>{const sc=checkRateLimit();if(!sc.allowed){if(sc.blocked)showSecurityBlock(sc.remaining);return}const raw=DOM.numbersInput.value.split('\n').filter(l=>l.trim()!=='');const valid=[],invalid=[];raw.forEach(l=>{const t=l.trim();isValidPhone(t)?valid.push(t):invalid.push(t)});if(invalid.length>0)showToast(`${invalid.length} número(s) inválido(s) removido(s). Apenas números de telefone válidos são aceitos.`);if(valid.length===0)return showToast('Insira pelo menos um número de telefone válido.');if(valid.length>20)return showToast('Máximo de 20 números permitidos.');if(!DOM.messageInput.value.trim())return showToast('Escreva a mensagem primeiro.');numberList=valid.map(n=>n.replace(/[\s+\-()\.]/g,''));currentIndex=0;switchScreen(DOM.sendingScreen);updateDisplay()});DOM.backBtn.addEventListener('click',()=>{if(confirm('Deseja realmente voltar? O progresso será perdido.'))switchScreen(DOM.setupScreen)});DOM.nextBtn.addEventListener('click',()=>{currentIndex++;if(currentIndex<numberList.length){updateDisplay();showToast('Próximo contato carregado')}else{alert('🎉 Todos os envios foram concluídos!');switchScreen(DOM.setupScreen);DOM.numbersInput.value='';DOM.messageInput.value='';DOM.countLabel.textContent='0 / 20 números'}});function updateDisplay(){if(rafId)cancelAnimationFrame(rafId);rafId=requestAnimationFrame(()=>{const c=numberList[currentIndex],m=encodeURIComponent(DOM.messageInput.value.trim());DOM.currentIndexEl.textContent=currentIndex+1;DOM.totalNumbersEl.textContent=numberList.length;DOM.currentNumberEl.textContent=c;DOM.sendLink.href=`https://wa.me/${c}?text=${m}`;const p=((currentIndex+1)/numberList.length)*100;DOM.progressBar.style.width=`${p}%`;DOM.progressPercent.textContent=`${Math.round(p)}%`})}function switchScreen(s){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));s.classList.add('active')}}));